#!/usr/bin/env node
/**
 * Copy the canonical locale catalogs into `src/locales/`.
 *
 * The catalogs live at `i18n/locales/` in the repository root so translators can
 * edit them without touching a web app. This script copies them in at build
 * time, which is more robust than importing across the project root: a
 * cross-root JSON import works in Vite but confuses TypeScript's rootDir rules,
 * and a build that depends on being run from one specific directory is a build
 * that breaks in CI.
 *
 * `src/locales/` is gitignored and regenerated by the npm `pre*` hooks.
 */
import { cpSync, existsSync, mkdirSync, readdirSync, rmSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const target = resolve(here, '..', 'src', 'locales');
const source = resolve(here, '..', '..', '..', 'i18n', 'locales');

if (!existsSync(source)) {
  console.error(
    `[sync-locales] canonical catalogs not found at ${source}.\n` +
      'The console cannot build without them. Run this script from within the repository.',
  );
  process.exit(1);
}

const files = readdirSync(source).filter((name) => name.endsWith('.json'));
if (files.length === 0) {
  console.error(`[sync-locales] ${source} contains no .json catalogs.`);
  process.exit(1);
}

rmSync(target, { recursive: true, force: true });
mkdirSync(target, { recursive: true });
for (const name of files) {
  cpSync(join(source, name), join(target, name));
}

console.log(`[sync-locales] copied ${files.length} catalog(s) from ${source}`);
